const __aivicBundle_9_validateDealStatusAndInvoiceAlignment = (() => {
  function validateDealStatusAndInvoiceAlignment(
    dealData: DealRecord,
    invoiceData: InvoiceRecord
  ): AlignmentCheckResult {
    if (dealData["dealAmount"] === undefined || dealData["dealAmount"] === null) { throw new Error("dealAmount is required"); }
    if (invoiceData["invoiceId"] === undefined || invoiceData["invoiceId"] === null) { throw new Error("invoiceId is required"); }
    if (invoiceData["dealId"] === undefined || invoiceData["dealId"] === null) { throw new Error("dealId is required"); }
    const dealId = dealData.dealId;
    const dealStatus = dealData.dealStatus;
    const plannedRevenueDate = dealData.plannedRevenueDate || new Date();
    const invoiceIssuedDate = invoiceData.invoiceIssuedDate || new Date();
  
    const timeDiffMs = invoiceIssuedDate.getTime() - plannedRevenueDate.getTime();
    const delayDays = Math.floor(timeDiffMs / (1000 * 60 * 60 * 24));
  
    const isAligned = delayDays === 0;
    const alignmentStatus = isAligned ? "ズレなし" : "ズレあり";
    const hasWarning = !isAligned;
    const hasError = false;
  
    let message = "";
    if (isAligned) {
      message = "商談ステータスと請求書発行日が一致しています";
    } else if (delayDays > 0) {
      message = `請求書発行が${delayDays}日遅延しています`;
    } else {
      message = `請求書発行が${Math.abs(delayDays)}日早期です`;
    }
  
    return {
      dealId,
      dealStatus,
      plannedRevenueDate,
      invoiceIssuedDate,
      alignmentStatus,
      hasWarning,
      hasError,
      delayDays,
      message,
    };
  }
  return { validateDealStatusAndInvoiceAlignment };
})();
