    const { dealRecord, invoiceRecord } = input;
  
    const dealAmount = dealRecord.dealAmount ?? dealRecord.amount ?? 0;
    const invoiceAmount =
      invoiceRecord.invoiceAmount ?? invoiceRecord.amount ?? 0;
  
    const amountDifference = dealAmount - invoiceAmount;
    const amountDifferencePercentage =
      dealAmount !== 0 ? (amountDifference / dealAmount) * 100 : 0;
  
    const hasAmountMismatch = amountDifference !== 0;
  
    let alignmentStatus = '正常';
    let warningMessage = '';
    let requiresApprovalReview = false;
  
    if (hasAmountMismatch) {
      alignmentStatus = '要確認';
      requiresApprovalReview = true;
      const absAmount = Math.abs(amountDifference);
      warningMessage = `金額ズレ：-${absAmount.toLocaleString('ja-JP')}円`;
    }
  
    return {
      alignmentStatus,
      hasAmountMismatch,
      amountDifference,
      amountDifferencePercentage,
      warningMessage,
      dealId: dealRecord.dealId,
      invoiceId: invoiceRecord.invoiceId,
      dealAmount,
      invoiceAmount,
      requiresApprovalReview,
    };
