/* AIVIC_FUNCTION_BUNDLE_START owner=detectMismatchesBetweenDealStatusAndInvoice exports=detectMismatchesBetweenDealStatusAndInvoice */
const __aivicBundle_21_detectMismatchesBetweenDealStatusAndInvoice = (() => {
  function detectMismatchesBetweenDealStatusAndInvoice(
    deals: Array<any>,
    invoices: Array<any>
  ): Array<{ dealId: string; invoiceId?: string; mismatchType: string; status: string }> {
    // 入力が空の場合は空配列を返す
    if (!deals || deals.length === 0 || !invoices || invoices.length === 0) {
      return [];
    }
  
    const mismatches: Array<{ dealId: string; invoiceId?: string; mismatchType: string; status: string }> = [];
  
    // 商談ごとに請求書との照合を実施
    for (const deal of deals) {
      const dealId = deal.dealId;
      if (!dealId) continue;
  
      // 該当する請求書を検索
      const matchingInvoices = invoices.filter((inv) => inv.dealId === dealId);
  
      // ケース1: 商談が存在するが請求書がない場合
      if (matchingInvoices.length === 0) {
        // 商談ステータスが「受注」「進行中」等の請求対象ステータスの場合、未請求として検出
        if (deal.status && ['受注', '進行中', 'Won', 'In Progress'].includes(deal.status)) {
          mismatches.push({
            dealId,
            mismatchType: 'unbilled',
            status: 'no_invoice_found',
          });
        }
        continue;
      }
  
      // ケース2: 商談と請求書の金額が一致しない場合
      for (const invoice of matchingInvoices) {
        const dealAmount = deal.dealAmount ?? deal.amount;
        const invoiceAmount = invoice.invoiceAmount ?? invoice.amount;
  
        if (dealAmount !== undefined && invoiceAmount !== undefined && dealAmount !== invoiceAmount) {
          mismatches.push({
            dealId,
            invoiceId: invoice.invoiceId,
            mismatchType: 'amount_mismatch',
            status: 'amount_discrepancy',
          });
        }
  
        // ケース3: 商談と請求書のステータスが一致しない場合
        const dealStatus = deal.dealStatus ?? deal.status;
        const invoiceStatus = invoice.invoiceStatus ?? invoice.status;
  
        if (dealStatus && invoiceStatus && dealStatus !== invoiceStatus) {
          // 特定のステータス組み合わせのみ不整合と判定
          const incompatiblePairs = [
            ['受注', '下書き'],
            ['Won', 'Draft'],
            ['キャンセル', '発行済み'],
            ['Cancelled', 'Issued'],
          ];
  
          const isIncompatible = incompatiblePairs.some(
            ([dStatus, iStatus]) => dealStatus === dStatus && invoiceStatus === iStatus
          );
  
          if (isIncompatible) {
            mismatches.push({
              dealId,
              invoiceId: invoice.invoiceId,
              mismatchType: 'status_mismatch',
              status: 'status_discrepancy',
            });
          }
        }
  
        // ケース4: 請求日が計画日から大きく遅延している場合
        const plannedDate = deal.plannedInvoiceDate ?? deal.billingScheduledDate;
        const actualDate = invoice.invoiceIssuedDate ?? invoice.issuedDate ?? invoice.issueDate;
  
        if (plannedDate && actualDate) {
          const planned = new Date(plannedDate).getTime();
          const actual = new Date(actualDate).getTime();
          const delayDays = Math.floor((actual - planned) / (1000 * 60 * 60 * 24));
  
          // 30日以上の遅延を検出
          if (delayDays > 30) {
            mismatches.push({
              dealId,
              invoiceId: invoice.invoiceId,
              mismatchType: 'billing_delay',
              status: 'delayed_invoice',
            });
          }
        }
      }
    }
  
    return mismatches;
  }
  return { detectMismatchesBetweenDealStatusAndInvoice };
})();
