const __aivicBundle_27_validateInvoiceApproval = (() => {
  function validateInvoiceApproval(invoiceData: {
    invoiceId: string;
    customerId: string;
    customerName: string;
    customerAddress?: string;
    customerPhoneNumber?: string;
    invoiceAmount: number;
    invoiceDate: string;
    dueDate: string;
    invoiceLineItems?: Array<{
      lineItemId: string;
      productName: string;
      quantity: number;
      unitPrice: number;
    }>;
    invoiceStatus?: string;
    invoiceLines?: Array<{
      lineId: string;
      itemName: string;
      quantity: number;
      unitPrice: number;
      lineAmount: number;
    }>;
    totalAmount?: number;
    status?: string;
    [key: string]: any;
  }): void {
    if (invoiceData["invoiceId"] === undefined || invoiceData["invoiceId"] === null) { throw new Error("invoiceId is required"); }
    // 顧客情報の検証
    if (!invoiceData.customerId || invoiceData.customerId.trim() === "") {
      throw new Error("顧客情報が不完全です: 顧客IDが必須です");
    }
  
    if (!invoiceData.customerName || invoiceData.customerName.trim() === "") {
      throw new Error("顧客情報が不完全です: 顧客名が必須です");
    }
  
    // 請求明細の検証
    const hasInvoiceLines =
      invoiceData.invoiceLines && invoiceData.invoiceLines.length > 0;
    const hasInvoiceLineItems =
      invoiceData.invoiceLineItems && invoiceData.invoiceLineItems.length > 0;
  
    if (!hasInvoiceLines && !hasInvoiceLineItems) {
      throw new Error("請求明細が空です: 最低1件の請求明細が必須です");
    }
  
    // 金額の検証
    if (
      invoiceData.invoiceAmount === undefined ||
      invoiceData.invoiceAmount === null ||
      invoiceData.invoiceAmount <= 0
    ) {
      throw new Error("請求金額が無効です: 0より大きい金額が必須です");
    }
  
    // 日付の検証
    if (!invoiceData.invoiceDate || invoiceData.invoiceDate.trim() === "") {
      throw new Error("請求日が必須です");
    }
  
    if (!invoiceData.dueDate || invoiceData.dueDate.trim() === "") {
      throw new Error("支払期限が必須です");
    }
  }
  return { validateInvoiceApproval };
})();
