/* AIVIC_FUNCTION_BUNDLE_START owner=detectDelayedBillingIssues exports=detectDelayedBillingIssues */
const __aivicBundle_30_detectDelayedBillingIssues = (() => {
  function detectDelayedBillingIssues(
    salesData: Array<{
      dealId: string;
      customerId: string;
      billingDate: Date;
      plannedAccrualDate: Date;
      amount: number;
      status: string;
    }>
  ): {
    delayedIssues: Array<{
      dealId: string;
      customerId: string;
      billingDate: Date;
      plannedAccrualDate: Date;
      delayDays: number;
      isDelayed: boolean;
      amount: number;
    }>;
    totalDelayedCount: number;
    totalDelayedAmount: number;
    detectionTimestamp: Date;
  } {
    const DELAY_THRESHOLD_DAYS = 30;
  
    const delayedIssues = salesData
      .map((sale) => {
        const delayMs =
          sale.plannedAccrualDate.getTime() - sale.billingDate.getTime();
        const delayDays = Math.ceil(delayMs / (1000 * 60 * 60 * 24));
        const isDelayed = delayDays >= DELAY_THRESHOLD_DAYS;
  
        return {
          dealId: sale.dealId,
          customerId: sale.customerId,
          billingDate: sale.billingDate,
          plannedAccrualDate: sale.plannedAccrualDate,
          delayDays,
          isDelayed,
          amount: sale.amount,
        };
      })
      .filter((issue) => issue.isDelayed);
  
    const totalDelayedCount = delayedIssues.length;
    const totalDelayedAmount = delayedIssues.reduce(
      (sum, issue) => sum + issue.amount,
      0
    );
  
    return {
      delayedIssues,
      totalDelayedCount,
      totalDelayedAmount,
      detectionTimestamp: new Date(),
    };
  }
  return { detectDelayedBillingIssues };
})();
export const detectDelayedBillingIssues = __aivicBundle_30_detectDelayedBillingIssues.detectDelayedBillingIssues;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectDelayedBillingIssues */

